public subroutine uf_globalmemorystatus (ref unsignedlong al_memoryload, ref unsignedlong al_totalphys, ref unsignedlong al_availphys, ref unsignedlong al_totalpagefile, ref unsignedlong al_availpagefile, ref unsignedlong al_totalvirtual, ref unsignedlong al_availvirtual);//====================================================================
// 函数: n_getmemorystatus_api.uf_globalmemorystatus()
//--------------------------------------------------------------------
// 描述:
//--------------------------------------------------------------------
// 参数:(单位MB)
// 	reference	long	al_MemoryLoad   	已装入内存
// 	reference	long	al_TotalPhys    	总物理内存
// 	reference	long	al_AvailPhys    	可用物理内存
// 	reference	long	al_TotalPageFile	分页大小
// 	reference	long	al_AvailPageFile	可用分页大小
// 	reference	long	al_TotalVirtual 	虚拟内存大小
// 	reference	long	al_AvailVirtual 	可用虚拟内存大小
//--------------------------------------------------------------------
// 返回:  (none)
//--------------------------------------------------------------------
// 作者:	syc		日期: 2010年07月26日
//====================================================================


//Type MEMORYSTATUS
//        dwLength As Long 系统字长
//        dwMemoryLoad As Long 已装入内存
//        dwTotalPhys As Long 总物理内存
//        dwAvailPhys As Long 可用物理内存
//        dwTotalPageFile As Long 分页大小
//        dwAvailPageFile As Long 可用分页大小
//        dwTotalVirtual As Long  虚拟内存大小
//        dwAvailVirtual As Long  可用虚拟内存大小
//End Type

MEMORYSTATUS ls_MEMORYSTATUS
GlobalMemoryStatus(ls_MEMORYSTATUS)

al_MemoryLoad=ls_MEMORYSTATUS.dwMemoryLoad
al_TotalPhys=ls_MEMORYSTATUS.dwTotalPhys /1048576
al_AvailPhys=ls_MEMORYSTATUS.dwAvailPhys /1048576
al_TotalPageFile=ls_MEMORYSTATUS.dwTotalPageFile /1048576
al_AvailPageFile=ls_MEMORYSTATUS.dwAvailPageFile /1048576
al_TotalVirtual=ls_MEMORYSTATUS.dwTotalVirtual /1048576
al_AvailVirtual=ls_MEMORYSTATUS.dwAvailVirtual /1048576

end subroutine

