public function string of_tohex (long al_num);// -----------------------------------------------------------------------------
// SCRIPT:     n_adapter.of_ToHex
//
// PURPOSE:    This function translates a long to string Hex.
//
// ARGUMENTS:  al_num	- Number to convert
//
// DATE        PROG/ID		DESCRIPTION OF CHANGE / REASON
// ----------  --------		-----------------------------------------------------
// 01/21/2006	RolandS		Initial coding
// -----------------------------------------------------------------------------

If al_num > 15 Then
	// recursive call to self
	Return of_ToHex(al_num / 16) + &
					of_HexChar(Mod(al_num,16))
Else
	Return of_HexChar(al_num)
End If

end function

public function string of_hexchar (integer ai_num);// -----------------------------------------------------------------------------
// SCRIPT:     n_adapter.of_HexChar
//
// PURPOSE:    This function converts a number from 0-15 to Hex character.
//
// ARGUMENTS:  ai_num	- Number to convert
//
// DATE        PROG/ID		DESCRIPTION OF CHANGE / REASON
// ----------  --------		-----------------------------------------------------
// 01/21/2006	RolandS		Initial coding
// -----------------------------------------------------------------------------

String ls_hex

If ai_num < 10 Then
	ls_hex = String(ai_num)
Else
	ls_hex = String(Char(ai_num + 55))
End If

Return ls_hex

end function

public function string of_geterrormsg (unsignedlong aul_error);// -----------------------------------------------------------------------------
// SCRIPT:     n_adapter.of_GetErrorMsg
//
// PURPOSE:    This function returns the error message that goes
//					with the error code from GetLastError.
//
// ARGUMENTS:  aul_error - Error code from GetLastError
//
// DATE        PROG/ID		DESCRIPTION OF CHANGE / REASON
// ----------  --------		-----------------------------------------------------
// 01/21/2006	RolandS		Initial coding
// -----------------------------------------------------------------------------

Constant ULong FORMAT_MESSAGE_FROM_SYSTEM = 4096
Constant ULong LANG_NEUTRAL = 0
String ls_buffer
ULong lul_rtn

ls_buffer = Space(200)

lul_rtn = FormatMessage(FORMAT_MESSAGE_FROM_SYSTEM, 0, & 				aul_error, LANG_NEUTRAL, ls_buffer, 200, 0)

Return Trim(ls_buffer)

end function

public function string uf_getip (string as_hostname);//====================================================================
// 函数: n_adapter.uf_getip()
//--------------------------------------------------------------------
// 描述:获取as_hostname的IP地址 
//--------------------------------------------------------------------
// 参数:
// 	value	string	as_hostname	
//--------------------------------------------------------------------
// 返回:  string
//--------------------------------------------------------------------
// 作者:	syc		日期: 2010年09月09日
//====================================================================


string ls_HostName 
WSAData lst_wsadata
long WS_VERSION_REQD= 257
IF WSAStartup(WS_VERSION_REQD, lst_wsadata) <> 0 THEN
	GOTO error_out 
END IF
ls_hostname=as_hostname
STRING ls_ipaddr 
long ll_lpHost,ll_lphostip
HOSTENT lst_host 
blob{4} lbt_ip

ll_lpHost = gethostbyname(ls_hostname) 
IF ll_lphost = 0 THEN 
	GOTO Error_out 
END IF 
RtlMoveMemory(lst_host,ll_lphost,16) 
RtlMoveMemory(ll_lphostip,lst_host.haddrlist,4) 
RtlMoveMemory(lbt_ip,ll_lphostip,lst_host.hLen) 

ls_ipaddr = string(asc(string(blobmid(lbt_ip,1,1)))) + "."
ls_ipaddr += string(asc(string(blobmid(lbt_ip,2,1)))) + "."
ls_ipaddr += string(asc(string(blobmid(lbt_ip,3,1)))) + "."
ls_ipaddr += string(asc(string(blobmid(lbt_ip,4,1))))

WSACleanup()
RETURN ls_ipaddr 
Error_out: 
WSACleanup()
return '0.0.0.0' 
end function

public function string uf_sendmsg (string as_serverip, string as_webport, string as_receiver, string as_msgtitle, string as_msg);//提醒助手,无需安装rtx和登录rtx
//====================================================================
// 函数: n_rtxsdk.uf_sendmsg()
//--------------------------------------------------------------------
// 描述:
//--------------------------------------------------------------------
// 参数:
// 	string	as_serverip	//服务器ip(rtx.fey.com)
// 	string	as_webport 	//Rtx http服务端口默认：8012
// 	string	as_receiver	//接收人，以逗号隔开
// 	string	as_msgtitle	
// 	string	as_msg     	
//--------------------------------------------------------------------
// 返回:  (none)
//--------------------------------------------------------------------
// 作者:	syc		日期: 2010年07月20日
//====================================================================

string ls_rtxurl
string ls_rtxuser
string ls_appname
string ls_args
blob lblb_args
long ll_length
string ls_header


INet linet
n_netresult_rtx lir_data

if isnull(as_msg) or as_msg='' then return '发送失败：as_msg为空'
if isnull(as_receiver) or as_receiver='' then return '发送失败：as_receiver为空'
if isnull(as_serverip) or as_serverip='' then return '发送失败：as_serverip为空'

if ls_rtxurl='' then ls_rtxurl='http://'+ as_serverip +':'+as_webport+'/SendNotifyUserName.cgi'

ls_appname=getapplication().appname
ls_args = 'receiver=' + as_receiver + '&title='+ as_msgtitle + ' ' + ls_appname + '&appname=' + ls_appname +'&okurl=about:blank&errurl=about:blank' + '&msg=' + as_msg + '   ' + string(today(),'yyyymmdd')+string(now(),'hhmmss')

lblb_args = Blob( ls_args )

ll_length = Len( lblb_args )

ls_header = "Content-Type: " + &
"application/x-www-form-urlencoded~n" + &
"Content-Length: " + String( ll_length ) + "~n~n"

linet=create inet
lir_data = CREATE n_netresult_rtx

ll_length=linet.PostURL( ls_rtxurl, lblb_args, & 	ls_header, long(as_webport),lir_data )

/*
ls_rtxurl=ls_rtxurl + '?receiver=' + as_receiver + '&title='+ as_msgtitle + ' ' + ls_appname + '&appname=' + ls_appname +'&okurl=about:blank&errurl=about:blank' + '&msg=' + as_msg + '   ' + string(today(),'yyyymmdd')+string(now(),'hhmmss')

linet=create inet
lir_data = CREATE n_netresult_rtx
linet.GetURL(ls_rtxurl, lir_data)*/
if pos(lir_data.uf_gethtml(),'操作成功')>0 then
	ls_rtxurl=''
else
	ls_rtxurl='发送失败：' + lir_data.uf_gethtml()

	ls_rtxurl='http://'+ as_serverip +':'+as_webport+'/SendRTXerror.cgi?receiver=' + as_receiver + '&title=RTX发送失败&okurl=about:blank&errurl=about:blank' + '&msg=' + ls_rtxurl + '   ' + string(today(),'yyyymmdd')+string(now(),'hhmmss')

end if
destroy lir_data
destroy linet 
return ls_rtxurl
end function

