public function string uf_sendnotify (string as_serverip, string as_webport, string as_receiver, string as_msgtitle, string as_msg, string as_delaytime);//
//====================================================================
// 函数: n_rtxsdk.uf_SendNotify()
//--------------------------------------------------------------------
// 描述:提醒助手,无需安装rtx和登录rtx发送连接格式[院内网|www.fey.com]
//--------------------------------------------------------------------
// 参数:
// 	string	as_serverip	//服务器ip(rtx.fey.com)
