// 	string	as_receiver	//接收人，以逗号隔开
// 	string	as_msgtitle	//标题
// 	string	as_msg    
// 	string	as_delaytime 消息提醒框的停留时间（毫秒），0表示不自动消失。
//--------------------------------------------------------------------
// 返回:  (none)
//--------------------------------------------------------------------
// 作者:	syc		日期: 2010年07月20日
//====================================================================

string ls_rtxurl
string ls_rtxuser

INet linet
n_netresult_rtx lir_data

if isnull(as_msg) or as_msg='' then return '发送失败：as_msg为空'
if isnull(as_receiver) or as_receiver='' then return '发送失败：as_receiver为空'
if isnull(as_serverip) or as_serverip='' then return '发送失败：as_serverip为空'

if ls_rtxurl='' then ls_rtxurl='http://'+ as_serverip +':'+as_webport+'/SendNotifyUserName2.cgi'

ls_rtxurl=ls_rtxurl + '?receiver=' + as_receiver + '&delaytime=' +as_delaytime+ '&title='+ as_msgtitle + '&msg=' + as_msg + '   ' + string(today(),'yyyymmdd')+string(now(),'hhmmss')

linet=create inet
lir_data = CREATE n_netresult_rtx
linet.GetURL(ls_rtxurl, lir_data)
if pos(lir_data.uf_gethtml(),'操作成功')>0 then
	ls_rtxurl=''
else
	ls_rtxurl='发送失败：' + lir_data.uf_gethtml()
end if
destroy lir_data
destroy linet 
return ls_rtxurl

end function

